const enProjectOverrides = {};

export const PROJECT_COPY = { en: enProjectOverrides, fr: frProjects, es: esProjects };
export function projectCopy(lang, project, field) {
  if (lang === "en") return PROJECT_COPY.en[project.slug]?.[field] ?? project[field];
  const bag = PROJECT_COPY[lang]?.[project.slug];
  if (!bag || !(field in bag)) throw new Error(`Missing ${lang} project copy: ${project.slug}.${field}`);
  return bag[field];
}
export function hasProjectCopy(lang, project, field) {
  if (lang === "en") return field in project;
  return field in (PROJECT_COPY[lang]?.[project.slug] || {});
}
